def pick(probs, r):
    c = 0
    for i, p in enumerate(probs):
        c += p
        if r < c:
            return i
    return len(probs) - 1
print(' '.join(str(pick([0.5,0.3,0.2], r)) for r in (0.1, 0.55, 0.95)))

