A = ['d1', 'd2', 'd3']
B = ['d3', 'd1', 'd4']
k = 60
scores = {}
for lst in (A, B):
    for rank, d in enumerate(lst, 1):
        scores[d] = scores.get(d, 0) + 1 / (k + rank)
print(' '.join(sorted(scores, key=scores.get, reverse=True)))

import json
tools = {'add': lambda a, b: a + b}
def call(req):
    d = json.loads(req)
    name = d['tool']
    if name not in tools:
        return 'error: unknown tool ' + name
    return str(tools[name](**d['args']))
print(call('{"tool":"add","args":{"a":2,"b":3}}'))
print(call('{"tool":"nope","args":{}}'))

script = [{'tool': 'mul', 'args': {'a': 6, 'b': 7}}, {'final': '42 apples'}]
tools = {'mul': lambda a, b: a * b}
MAX_STEPS = 3
for step in script[:MAX_STEPS]:
    if 'final' in step:
        print('FINAL', step['final'])
        break
    r = tools[step['tool']](**step['args'])
